package TallerDePractica;

public class EJ07 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

	int a = 12, b = 5;
	
	System.out.println("a>b: " + (a > b));
	System.out.println("a==b: " + (a == b));
	System.out.println("a%b==0: " + (a % b == 0));
	System.out.println("a>b && b>0: " + (a > b && b > 0));
	
	}

}
